// Normaliza los datos que llegan del formulario web.
// Ajusta los nombres de campo a los de tu propio formulario.
const d = $input.first().json.body || $input.first().json;
return [{ json: {
  nombre: (d.nombre || d.name || '').trim(),
  email: (d.email || '').trim().toLowerCase(),
  telefono: (d.telefono || d.phone || '').trim(),
  mensaje: (d.mensaje || d.message || '').trim(),
  origen: d.origen || 'formulario web',
  recibido: new Date().toISOString()
} }];

