// Extrae el JSON devuelto por el modelo y lo une a los datos de la consulta.
const ia = $input.first().json;
let salida = {};
try {
  salida = JSON.parse(ia.choices[0].message.content);
} catch (e) {
  salida = { categoria: 'otro', urgencia: 'media', resumen: 'No se pudo interpretar la respuesta de la IA', respuesta: '' };
}
const consulta = $('Normalizar datos').first().json;
return [{ json: { ...consulta, ...salida } }];

